__global__ void copy_factor_convert_panel_kernel(
        const float* __restrict__ factor,
        float* __restrict__ output,
        int leading_output,
        const float* __restrict__ source,
        __half* __restrict__ compact,
        int rows,
        int leading_source) {
    constexpr int tile_size = 32;
    constexpr int factor_tiles = 4096 / tile_size;
    constexpr int groups_per_row = 512;
    constexpr int conversion_blocks = 4096;
    __shared__ float tile[tile_size][tile_size + 1];

    const int linear_thread = threadIdx.y * blockDim.x + threadIdx.x;
    const int threads = blockDim.x * blockDim.y;
    const int64_t groups = static_cast<int64_t>(rows) * groups_per_row;
    if (blockIdx.x < conversion_blocks) {
        for (int64_t index =
                 static_cast<int64_t>(blockIdx.x) * threads + linear_thread;
             index < groups;
             index += static_cast<int64_t>(conversion_blocks) * threads) {
            const int row = static_cast<int>(index >> 9);
            const int group = static_cast<int>(index & (groups_per_row - 1));
            const float4* vectors = reinterpret_cast<const float4*>(
                source + static_cast<int64_t>(row) * leading_source);
            const float4 first = vectors[group * 2];
            const float4 second = vectors[group * 2 + 1];
            __half2* destination = reinterpret_cast<__half2*>(
                compact + static_cast<int64_t>(row) * 4096);
            destination[group * 4] = __floats2half2_rn(first.x, first.y);
            destination[group * 4 + 1] = __floats2half2_rn(first.z, first.w);
            destination[group * 4 + 2] = __floats2half2_rn(second.x, second.y);
            destination[group * 4 + 3] = __floats2half2_rn(second.z, second.w);
        }
    }
    __syncthreads();

    const int tile_col = static_cast<int>(blockIdx.x) & (factor_tiles - 1);
    const int tile_row = static_cast<int>(blockIdx.x) >> 7;
    const int row_base = tile_row * tile_size;
    const int col_base = tile_col * tile_size;
    if (tile_row < tile_col) {
        for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
            for (int x = threadIdx.x; x < tile_size; x += blockDim.x) {
                output[
                    static_cast<int64_t>(row_base + y) * leading_output
                    + col_base + x
                ] = 0.0f;
            }
        }
        return;
    }
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        for (int x = threadIdx.x; x < tile_size; x += blockDim.x) {
            tile[y][x] = factor[
                row_base + x + static_cast<int64_t>(col_base + y) * 4096
            ];
        }
    }
    __syncthreads();
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        const int row = row_base + y;
        for (int x = threadIdx.x; x < tile_size; x += blockDim.x) {
            const int col = col_base + x;
            output[static_cast<int64_t>(row) * leading_output + col] =
                row >= col ? tile[x][y] : 0.0f;
        }
    }
}

